<template>
  <teleport to="body">
    <div class="modal-mask" :style="{ zIndex: zIndex, ...maskStyle,alignItems:placementP }" @click="handleMaskClick">
      <div class="modal-wrapper" @click.stop>
        <slot />
      </div>
    </div>
  </teleport>
</template>

<script setup>
import { computed } from 'vue';
const props = defineProps({
  zIndex: Number,
  maskClosable: { type: Boolean, default: true },
  onClose: Function,
  maskStyle: Object,
  placement:{type:String,default:'center'}
})

const placementP = computed(() => {
  if(props.placement == 'center'){
    return 'center'
  }else if(props.placement == 'top'){
    return 'flex-start'
  }else if(props.placement == 'bottom'){
    return 'flex-end'
  }
})

function handleMaskClick() {
  if (props.maskClosable) props.onClose?.()
}
</script>

<style scoped>
.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
}
</style>
