// src/utils/zIndexManager.js

const BASE_Z_INDEX = 3000
let modalStack = []

/** 打开新 modal，返回 zIndex */
export function dialogPushZIndex() {
  const zIndex = BASE_Z_INDEX + modalStack.length
  modalStack.push(zIndex)
  return zIndex
}

/** 关闭 modal，释放最上层 zIndex */
export function dialogPopZIndex() {
  modalStack.pop()
}

/** 获取当前最顶部 z-index（不增加） */
export function dialogGetCurrentZIndex() {
  return modalStack[modalStack.length - 1] || BASE_Z_INDEX
}

/** 重置所有 z-index（可在页面销毁时调用） */
export function dialogResetZIndex() {
  modalStack = []
}
