import { createVNode, render } from 'vue'
import { dialogPushZIndex, dialogPopZIndex } from './z-index-manager'
  
/**
 * 打开一个模态框
 * 动态创建一个组件实例并渲染到页面中
 * 
 * @param {Function} Component 要渲染的组件构造函数
 * @param {Object} props 传递给组件的属性，默认为空对象
 * @param {Object} slots 传递给组件的插槽内容，默认为空对象
 * @returns {Object} 包含关闭模态框的函数的对象
 */
export function openModal(Component, props = {}, slots = {}) {
  // 创建一个容器元素，用于渲染模态框
  const container = document.createElement('div')
  // 将容器元素添加到页面的 body 中
  document.body.appendChild(container)

  // 获取当前的 zIndex 值，并将其推入 zIndex 栈中
  const zIndex = dialogPushZIndex()

  // 定义关闭模态框的函数
  const close = () => {
    // 渲染空内容以移除当前的 vnode
    render(null, container)
    // 从 DOM 中移除容器元素
    container.remove()
    // 从 zIndex 栈中弹出当前的 zIndex 值
    dialogPopZIndex()
  }

  // 将 close 函数注入到 props 中，以便组件可以使用它来关闭模态框
  const finalProps = injectCloseIntoHandlers({ ...props, zIndex, onClose: close }, close)

  // 创建组件的虚拟节点
  const vnode = createVNode(Component, finalProps, slots)
  // 将虚拟节点渲染到容器中
  render(vnode, container)

  // 返回一个对象，包含关闭模态框的函数
  return { close }
}

/**
 * 将关闭模态框的函数注入到事件处理函数中
 * 
 * @param {Object} props 组件的属性对象
 * @param {Function} close 关闭模态框的函数
 * @returns {Object} 包含注入了关闭函数的事件处理函数的对象
 */
function injectCloseIntoHandlers(props, close) {
  // 复制 props 对象，避免直接修改原始对象
  const wrapped = { ...props }

  // 遍历 props 对象的所有键
  Object.keys(props).forEach(key => {
    // 检查值是否为函数，并且键以 'on' 开头，表示是一个事件处理函数
    if (typeof props[key] === 'function' && key.startsWith('on')) {
      // 用 close 函数包装原始的事件处理函数
      wrapped[key] = (...args) => {
        // 把 close 作为第一个参数传进去， followed by any additional arguments
        return props[key](close, ...args)
      }
    }
  })

  // 返回包含注入了关闭函数的事件处理函数的新 props 对象
  return wrapped
}
